function containsLink(tokens: Token[]): boolean {
  return tokens.some(t => t.type === 'link' || ('tokens' in t && Array.isArray(t.tokens) && containsLink(t.tokens)));
}

function outputLink(cap: string[], link: Pick<Tokens.Link, 'href' | 'title'>, raw: string, lexer: _Lexer, rules: Rules): Tokens.Link | Tokens.Image | Tokens.Text {
  const href = link.href;
  const title = link.title || null;
  const text = cap[1].replace(rules.other.outputLinkReplace, '$1');
  const type = cap[0].charAt(0) === '!' ? 'image' : 'link';

  const prevInLink = lexer.state.inLink;
  lexer.state.inLink = true;
  const tokens = lexer.inlineTokens(text);
  lexer.state.inLink = prevInLink;

  // links may not contain other links, at any level of nesting
  if (type === 'link' && containsLink(tokens)) {
    return {
      type: 'text',
      raw: '[',
      text: '[',
    };
  }

  return {
    type,
    raw,
    href,
    title,
    text,
    tokens,
  };
}

